if(!exists('vintage_backtest',mode='function'))library(creditratingsystem)
origins<-lapply(0:99,function(i)list(account_id=paste0('a',i),opened_at='2024-01-01',known_at='2024-01-01',original_balance=100,currency='EUR',cluster_id=paste0('g',i)))
events<-c(lapply(0:19,function(i)list(event_id=paste0('exit',i),account_id=paste0('a',i),event_type='PREPAID',occurred_at='2024-01-20',known_at='2024-01-20')),lapply(20:29,function(i)list(event_id=paste0('default',i),account_id=paste0('a',i),event_type='DEFAULT',occurred_at='2024-02-15',known_at='2024-02-15')));coverage<-lapply(0:99,function(i)list(account_id=paste0('a',i),observed_through='2024-03-31',known_at='2024-04-01'))
table<-build_vintage_performance(origins,list(),events,months_on_book=c(0,1),evaluation_cutoff='2024-04-01',coverage=coverage,default_event='DEFAULT',delinquency_states='DPD30',exit_events='PREPAID')$value;predictions<-outcomes<-list()
for(i in 0:99)for(mob in 0:1){end<-c('2024-01-31','2024-02-29')[mob+1];predictions[[length(predictions)+1]]<-list(account_id=paste0('a',i),months_on_book=mob,model_id='vintage',model_version='1',parameter_version='1',forecast_at='2024-01-01',known_at='2024-01-01',cumulative_pd=c(.05,.15)[mob+1],interval_pd=c(.05,.1)[mob+1]);default<-i>=20&&i<30&&mob==1;exited<-i<20;out<-list(account_id=paste0('a',i),months_on_book=mob,period_end=end,known_at='2024-04-01',default_definition='first-default-before-exit',complete=TRUE,exited=exited,cumulative_default=as.numeric(default),interval_default=as.numeric(default),complete_through=end);if(default||exited){out$event_id<-paste0(if(default)'default'else'exit',i);out$first_event_at<-if(default)'2024-02-15'else'2024-01-20'};outcomes[[length(outcomes)+1]]<-out}
d<-list(model_id='vintage',model_version='1',parameter_version='1',data_fingerprint='fixed-100',population_id='origin-cohort',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2024-04-01',target=list(event='default',horizon=1,time_unit='months',probability_measure='PHYSICAL',conditioning='performing'));contract<-list(method='fixed_origination',weighting='count',exit_treatment='first_competing_exit',reference='original-cohort',default_definition='first-default-before-exit',horizon_convention='origination_month_end_plus_mob')
run<-function()vintage_backtest(table,predictions,outcomes,origin_cohorts=origins,denominator_contract=contract,design=d,uncertainty='cluster_bootstrap',cluster_resamples=list(rep('g0',100),rep('g20',100)))$value
r<-run();last<-r$metrics$cells[[2]];stopifnot(last$original_accounts==100,last$counts$exits==20,abs(last$cumulative$mean_outcome-.1)<1e-14,abs(last$cumulative$bias-.05)<1e-14,abs(last$cumulative$brier-.0925)<1e-14,last$remaining_first_event_risk_count==70,abs(r$uncertainty$intervals[['2024-01/EUR/1/cumulative/brier']]$lower-.04)<1e-14)
coverage[[100]]$observed_through<-'2024-01-31';table<-build_vintage_performance(origins,list(),events,months_on_book=c(0,1),evaluation_cutoff='2024-04-01',coverage=coverage,default_event='DEFAULT',delinquency_states='DPD30',exit_events='PREPAID')$value;outcomes[[200]]$complete<-FALSE;outcomes[[200]]['cumulative_default']<-list(NULL);outcomes[[200]]['interval_default']<-list(NULL);r<-run();last<-r$metrics$cells[[2]];stopifnot(last$original_accounts==100,!last$mature,is.null(last$cumulative$brier),is.null(last$cumulative$mean_outcome),identical(last$missing_followup_accounts,list('a99')))
